    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Minimum insurance limits shall be: CGL: $2,000,000 per occurrence / $5,000,000 aggregate; E&O: $3,000,000 per claim / $5,000,000 aggregate; Umbrella: $10,000,000 per occurrence and aggregate; Auto: $1,000,000 combined single limit; Employers Liability: $1,000,000 per accident.', ARRAY['minimum insurance limits','CGL','$2,000,000 per occurrence','$5,000,000 aggregate','E&O','$3,000,000 per claim','$5,000,000 aggregate','Umbrella','$10,000,000','Auto','$1,000,000 combined single limit','Employers Liability','$1,000,000 per accident']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard minimum limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard minimum limits appropriate for typical productions. E&O at $3M/$5M provides adequate content liability coverage. $10M umbrella supplements primary limits."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For productions with budgets exceeding $25,000,000, the following enhanced limits shall apply: CGL: $5,000,000 per occurrence / $10,000,000 aggregate; E&O: $5,000,000 per claim / $10,000,000 aggregate; Umbrella: $25,000,000 per occurrence and aggregate.', ARRAY['productions','budgets exceeding','$25,000,000','enhanced limits','CGL','$5,000,000 per occurrence','$10,000,000 aggregate','E&O','$5,000,000 per claim','$10,000,000 aggregate','Umbrella','$25,000,000']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Enhanced limits for large productions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Budget-scaled limits for larger productions appropriately match insurance to production scope. Higher limits for higher-budget content reflect greater exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Errors and Omissions insurance shall provide coverage for: (a) copyright and trademark infringement; (b) defamation, libel, and slander; (c) invasion of privacy and publicity rights; (d) infliction of emotional distress; (e) breach of contract (third party); and (f) negligent misrepresentation. Defense costs shall be in addition to, not within, policy limits.', ARRAY['Errors and Omissions','coverage','copyright','trademark infringement','defamation','libel','slander','invasion of privacy','publicity rights','infliction','emotional distress','breach of contract','negligent misrepresentation','defense costs','in addition to','not within','policy limits']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "E&O coverage scope with defense outside limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive E&O coverage scope addressing all content-related claims. Defense costs outside limits is preferred structure preserving full limits for damages."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, in its reasonable discretion, require increased limits based on: (a) unusual production risks (stunts, pyrotechnics, exotic locations); (b) use of minors; (c) documentary content involving public figures; (d) true crime or controversial subject matter; or (e) other factors creating elevated liability exposure.', ARRAY['Amazon','reasonable discretion','require','increased limits','unusual production risks','stunts','pyrotechnics','exotic locations','minors','documentary','public figures','true crime','controversial','elevated liability exposure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Discretionary limit increases", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s discretion to require increased limits for elevated-risk scenarios ensures coverage matches actual risk profile. Enumerated factors provide guidance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The E&O policy shall have a deductible or self-insured retention of no more than $50,000. ProdCo shall be responsible for payment of any deductible or retention. Amazon shall be included in the policy as a loss payee for any deductible recovery.', ARRAY['E&O policy','deductible','self-insured retention','no more than','$50,000','ProdCo','responsible','payment','deductible','retention','Amazon','loss payee','deductible recovery']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Deductible limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasonable deductible cap ensures coverage is accessible without significant first-dollar exposure. ProdCo responsibility and loss payee status protects Amazon."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Minimum limits specified herein are per-project minimums. If ProdCo maintains corporate policies covering multiple productions, such policies shall have aggregate limits sufficient to provide not less than the specified per-project minimums for this production while maintaining adequate reserves for other covered productions.', ARRAY['minimum limits','per-project minimums','corporate policies','multiple productions','aggregate limits','sufficient','per-project minimums','this production','adequate reserves','other covered productions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Corporate policy adequacy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses corporate policies covering multiple productions. Requires adequate reserves to ensure this production has effective minimums despite aggregation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Insurance limits shall be maintained at the specified minimums throughout the term of this Agreement and for a period of not less than five (5) years following final delivery of the Program. If any policy is cancelled or limits reduced, ProdCo shall obtain replacement coverage immediately.', ARRAY['insurance limits','maintained','specified minimums','throughout term','five years','following','final delivery','Program','policy','cancelled','limits reduced','obtain','replacement coverage','immediately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Maintenance period with replacement requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-year post-delivery maintenance ensures coverage for latent claims. Immediate replacement requirement addresses mid-term coverage lapses."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Minimum limits shall apply. If any required policy is offered only with higher deductibles or retentions than specified, ProdCo shall accept such terms provided the deductible does not exceed $100,000 per occurrence, and ProdCo demonstrates financial capacity to cover such retention.', ARRAY['minimum limits','apply','policy','higher deductibles','retentions','than specified','accept','terms','deductible','not exceed','$100,000','per occurrence','financial capacity','cover','retention']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Higher deductible flexibility", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Flexibility on higher deductibles up to $100K may be acceptable given market conditions. Financial capacity demonstration protects Amazon from unfunded retentions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Specified minimum limits apply. For unscripted/reality productions, E&O limits may be reduced to $2,000,000 per claim / $3,000,000 aggregate given the lower content liability typically associated with such formats, subject to Amazon approval.', ARRAY['minimum limits','apply','unscripted','reality productions','E&O limits','reduced','$2,000,000 per claim','$3,000,000 aggregate','lower content liability','formats','Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Reduced limits for unscripted", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Lower E&O for unscripted may be acceptable if Amazon approves based on specific content. Some reality content has higher risk; approval requirement preserves discretion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Limits shall meet specified minimums. If ProdCo maintains an annual policy with aggregate limits that may be eroded by claims on other projects, ProdCo shall monitor aggregate availability and notify Amazon if remaining aggregate falls below 75% of policy aggregate.', ARRAY['limits','specified minimums','annual policy','aggregate limits','eroded','claims','other projects','monitor','aggregate availability','notify Amazon','remaining aggregate','falls below','75%','policy aggregate']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Aggregate monitoring obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Aggregate monitoring for multi-project policies addresses erosion risk. 75% threshold provides early warning before limits become inadequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Minimum limits are specified above. Defense costs may be within policy limits (eroding limits) for E&O policies if defense-outside-limits coverage is not available in the market or would require premium exceeding 125% of defense-within premium.', ARRAY['minimum limits','defense costs','within policy limits','eroding limits','E&O','defense-outside-limits','not available','market','premium exceeding','125%','defense-within premium']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Defense-within-limits exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense-within-limits is less favorable but may be acceptable with market availability exception. Premium threshold provides objective standard for exception."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'E&O coverage shall be maintained for five years post-delivery. If obtaining a five-year tail is cost-prohibitive (exceeding 200% of annual premium), ProdCo shall purchase a three-year tail and notify Amazon, and the parties shall discuss allocation of post-tail risk.', ARRAY['E&O','maintained','five years','post-delivery','five-year tail','cost-prohibitive','exceeding','200%','annual premium','purchase','three-year tail','notify Amazon','discuss','allocation','post-tail risk']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Tail cost flexibility", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tail cost exception with 200% threshold may be acceptable for extraordinary pricing. Three-year minimum tail and allocation discussion preserves protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Limits shall be maintained as specified. Amazon acknowledges that E&O limits are shared across the policy period and may be reduced by claims. Amazon may require ProdCo to reinstate limits if aggregate is materially reduced during production.', ARRAY['limits','maintained','specified','acknowledges','E&O limits','shared','policy period','reduced','claims','require','ProdCo','reinstate limits','aggregate','materially reduced','during production']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Limit reinstatement right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of aggregate erosion with reinstatement right addresses practical policy mechanics while preserving Amazon''s protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance limits shall be determined by ProdCo based on industry standards and production budget. ProdCo represents that it maintains adequate insurance for its operations and shall ensure coverage is appropriate for this production.', ARRAY['insurance limits','determined by ProdCo','industry standards','production budget','represents','maintains','adequate insurance','operations','ensure','coverage','appropriate','production']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "ProdCo-determined limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined limits with no Amazon-specified minimums provides no protection. Amazon must specify minimum limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'E&O insurance with limits of $500,000 per claim and $1,000,000 aggregate shall be sufficient for this production, which is consistent with independent production industry standards.', ARRAY['E&O insurance','$500,000 per claim','$1,000,000 aggregate','sufficient','production','consistent','independent production','industry standards']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Inadequate E&O limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$500K/$1M E&O limits are grossly inadequate for Amazon content. Single content claim can easily exceed these limits. Minimum should be $3M/$5M."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Minimum limits shall apply only during active production. Following completion of principal photography, limits may be reduced by 50%. Following final delivery, ProdCo shall maintain only statutory minimum coverages.', ARRAY['minimum limits','only during','active production','following completion','principal photography','limits','reduced','50%','following final delivery','maintain','only','statutory minimum']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Post-production limit reductions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Post-production limit reductions to 50% or statutory minimums leaves Amazon exposed when content claims are most likely to arise (after release). Full limits must be maintained through tail period."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance limits specified herein are aspirational targets. ProdCo shall use best efforts to obtain such limits but shall not be in breach if lower limits are obtained, provided coverage is commercially reasonable for productions of this type.', ARRAY['limits','specified','aspirational targets','best efforts','obtain','limits','not be in breach','lower limits','obtained','coverage','commercially reasonable','productions']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Aspirational limits only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Aspirational'' limits with no breach for lower amounts effectively makes limits optional. Insurance minimums must be mandatory requirements, not targets."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance. The policy may contain standard industry exclusions including exclusions for: prior knowledge; intellectual property claims; claims by investors or financiers; intentional acts; and cyber-related claims.', ARRAY['E&O insurance','policy','standard industry exclusions','prior knowledge','intellectual property claims','investors','financiers','intentional acts','cyber-related claims']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Excessive E&O exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Intellectual property exclusion in E&O defeats primary purpose of the coverage. Some exclusions are standard (intentional acts), but IP exclusion is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Limits shall be shared between Amazon''s productions covered under ProdCo''s policy. The specified limits are total aggregate limits across all Amazon projects, not per-project limits.', ARRAY['limits','shared','Amazon''s productions','ProdCo''s policy','specified limits','total aggregate','across all','Amazon projects','not per-project']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Shared limits across Amazon projects", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shared limits across multiple Amazon projects could leave this production without adequate coverage if other projects have claims. Per-project minimums are required."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall deliver to Amazon certificates of insurance evidencing all required coverages within ten (10) business days of the Effective Date and prior to commencement of any production activities. Certificates shall specifically identify the production covered and confirm compliance with all requirements set forth herein.', ARRAY['deliver','Amazon','certificates of insurance','evidencing','required coverages','ten business days','Effective Date','prior to','commencement','production activities','specifically identify','production','confirm compliance','requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate delivery timing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear certificate delivery timeline with requirement to deliver before production begins. Production identification and compliance confirmation ensure proper documentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Certificates of insurance shall: (a) identify Amazon as additional insured; (b) confirm primary and non-contributory status; (c) evidence waiver of subrogation; (d) state policy limits meeting or exceeding required minimums; and (e) provide that Amazon shall receive not less than thirty (30) days'' notice of cancellation, non-renewal, or material modification.', ARRAY['certificates of insurance','identify','Amazon','additional insured','confirm','primary','non-contributory','evidence','waiver of subrogation','state','policy limits','meeting','exceeding','minimums','Amazon','receive','thirty days','notice','cancellation','non-renewal','material modification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate content requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive certificate content requirements ensuring all key terms are documented on face of certificate. Cancellation notice requirement is essential."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s request, ProdCo shall provide copies of actual insurance policies, including all endorsements, within ten (10) business days of such request. Amazon may request policy copies at any time and from time to time throughout the term.', ARRAY['Amazon''s request','provide','copies','actual insurance policies','including','endorsements','ten business days','request','any time','from time to time','throughout term']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Policy copy request right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Right to request actual policy copies allows Amazon to verify coverage terms beyond certificate face. Ten-day turnaround is reasonable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall provide updated certificates: (a) annually, no later than the policy renewal date; (b) upon any policy change, cancellation, or replacement; (c) upon request by Amazon; and (d) upon any change in the production scope that may affect coverage requirements.', ARRAY['updated certificates','annually','policy renewal date','policy change','cancellation','replacement','request','Amazon','change','production scope','affect','coverage requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate update triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple certificate update triggers ensure Amazon has current coverage information throughout production. Annual, change-based, and scope-based updates provide comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to deliver required certificates or policies, or delivery of certificates evidencing non-compliant coverage, shall constitute a material breach entitling Amazon to suspend production and all payments until compliant documentation is provided.', ARRAY['failure','deliver','required certificates','policies','delivery','certificates','non-compliant coverage','material breach','entitling','Amazon','suspend','production','payments','compliant documentation','provided']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate failure consequences", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Material breach characterization for certificate failures with suspension right ensures compliance. Production should not proceed without proper insurance documentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Certificates shall be issued on ACORD form 25 (or equivalent) and shall be executed by an authorized representative of the insurer or an authorized agent. Certificates issued by brokers without binding authority shall not be acceptable unless accompanied by evidence of broker authority.', ARRAY['certificates','ACORD form 25','equivalent','executed','authorized representative','insurer','authorized agent','certificates','brokers','without binding authority','not acceptable','accompanied','evidence','broker authority']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate form and execution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ACORD 25 specification ensures standardized format. Authorized representative requirement and broker authority verification prevent questionable certificates."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain copies of all insurance policies and certificates for not less than ten (10) years following completion of the Program. Upon Amazon''s request during such period, ProdCo shall provide copies within twenty (20) business days.', ARRAY['maintain','copies','insurance policies','certificates','ten years','following','completion','Program','Amazon''s request','during','period','provide copies','twenty business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Long-term document retention", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ten-year retention requirement ensures documentation is available for latent claims. Longer response time (20 days) is reasonable for archived documents."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall deliver certificates within ten (10) business days of the Effective Date. If certificates are not available within such period due to insurer processing delays, ProdCo shall provide a binder or cover note, with final certificates to follow within twenty (20) business days.', ARRAY['certificates','ten business days','Effective Date','not available','insurer processing delays','provide','binder','cover note','final certificates','follow','twenty business days']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Binder for processing delay", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Binder as temporary evidence for insurer delays is acceptable industry practice. Twenty-day follow-up for final certificates is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may request policy copies. ProdCo shall provide copies within fifteen (15) business days, provided that ProdCo may redact premium information and information relating to other insureds or productions unrelated to this Agreement.', ARRAY['Amazon','request','policy copies','provide copies','fifteen business days','redact','premium information','information','other insureds','productions','unrelated','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Redaction rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Redaction of premium and unrelated insured information is reasonable confidentiality protection. Doesn''t affect Amazon''s ability to verify coverage terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Certificates evidencing E&O coverage may be delivered separately from other certificates if E&O is placed through a specialty broker requiring additional processing time. E&O certificates shall be delivered no later than thirty (30) days after the Effective Date.', ARRAY['certificates','E&O coverage','delivered separately','other certificates','specialty broker','additional processing time','E&O certificates','delivered','thirty days','Effective Date']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Separate E&O timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extended E&O timeline for specialty placement may be acceptable given market realities. Thirty days is reasonable maximum."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon objects to any certificate as not evidencing required coverage, Amazon shall notify ProdCo in writing of the specific deficiency within ten (10) business days. ProdCo shall have five (5) business days to provide clarification or replacement certificate.', ARRAY['Amazon objects','certificate','not evidencing','required coverage','notify ProdCo','writing','specific deficiency','ten business days','ProdCo','five business days','clarification','replacement certificate']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Certificate objection process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Certificate objection process with specific deficiency identification is reasonable. Provides ProdCo opportunity to address issues before breach is triggered."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Certificates shall be delivered electronically to the email address designated by Amazon''s risk management department. Physical certificates shall not be required unless specifically requested by Amazon for regulatory or financing purposes.', ARRAY['certificates','delivered electronically','email address','designated','Amazon''s risk management','physical certificates','not required','unless','specifically requested','Amazon','regulatory','financing purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Electronic delivery acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Electronic delivery is standard practice and acceptable. Physical certificate option for specific purposes provides flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Renewal certificates shall be delivered not less than fifteen (15) days prior to expiration of the current policy. If renewal terms include any reduction in limits, increase in deductibles, or addition of exclusions, ProdCo shall notify Amazon at least thirty (30) days prior to renewal.', ARRAY['renewal certificates','delivered','fifteen days','prior to expiration','current policy','renewal terms','reduction','limits','increase','deductibles','addition','exclusions','notify Amazon','thirty days','prior to renewal']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Renewal certificate timing and change notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pre-expiration delivery requirement and advance notice of adverse changes ensures Amazon has visibility into coverage continuity. Reasonable timing requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide certificates of insurance upon Amazon''s request. No automatic delivery or update requirements shall apply. Amazon shall be responsible for requesting certificates when needed.', ARRAY['provide','certificates','upon request','no automatic delivery','update requirements','apply','Amazon','responsible','requesting','when needed']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Request-only certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Request-only certificates without automatic delivery shifts monitoring burden to Amazon. Certificates must be delivered automatically at specified times."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall deliver certificates evidencing insurance coverage. Certificates shall be for informational purposes only and shall not create any contractual obligation to maintain coverage or give Amazon any rights under the policies.', ARRAY['deliver','certificates','evidencing','insurance','informational purposes only','not create','contractual obligation','maintain coverage','give Amazon','rights','under policies']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Informational only certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Informational purposes only'' disclaimer defeats purpose of certificate requirement. Certificates must confirm contractual coverage obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may request policy copies but shall reimburse ProdCo''s reasonable costs of obtaining and providing copies. ProdCo shall have thirty (30) business days to respond to policy copy requests.', ARRAY['Amazon','request','policy copies','reimburse','ProdCo''s reasonable costs','obtaining','providing copies','thirty business days','respond','requests']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Cost reimbursement for copies", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Cost reimbursement for policy copies and 30-day response time is unreasonable. Standard document requests should be at ProdCo''s cost with reasonable turnaround."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Certificates shall be accepted as delivered unless Amazon provides written objection within five (5) business days. Absence of timely objection shall constitute Amazon''s acceptance that all insurance requirements have been satisfied.', ARRAY['certificates','accepted as delivered','unless','Amazon','written objection','five business days','absence','timely objection','constitute','Amazon''s acceptance','insurance requirements','satisfied']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Deemed acceptance of certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed acceptance for non-objection shifts verification burden to Amazon with very short timeline. Certificates must comply regardless of Amazon''s review."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide certificates. ProdCo''s compliance with certificate requirements shall be satisfied by delivery of certificates; Amazon shall have no right to verify actual policy terms, endorsements, or coverage conditions beyond what appears on the certificate face.', ARRAY['provide','certificates','compliance','certificate requirements','satisfied','delivery','certificates','Amazon','no right','verify','actual policy terms','endorsements','coverage conditions','beyond','certificate face']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "No policy verification right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating policy verification right leaves Amazon unable to confirm actual coverage matches certificates. Certificate-only compliance is insufficient protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Failure to timely deliver certificates shall not be a material breach. ProdCo shall have a reasonable cure period of not less than sixty (60) days to deliver required certificates before any breach-based remedies may be exercised.', ARRAY['failure','timely deliver','certificates','not','material breach','reasonable cure period','sixty days','deliver','required certificates','breach-based remedies','exercised']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Extended cure for certificate failure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Non-material characterization and 60-day cure for certificate failure allows production without insurance documentation. Suspension right upon non-delivery must be preserved."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain in strict confidence and shall not disclose to any third party any Confidential Information of Amazon, including without limitation: (a) the terms and conditions of this Agreement; (b) Amazon''s business plans, strategies, and projections; (c) Amazon''s non-public financial information; (d) Amazon''s technology, systems, and processes; and (e) any other information designated as confidential by Amazon.', ARRAY['maintain','strict confidence','not disclose','third party','Confidential Information','Amazon','terms','conditions','Agreement','business plans','strategies','projections','non-public financial','technology','systems','processes','designated','confidential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard confidentiality scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive confidentiality scope covering Agreement terms, business information, financial data, and technology. Catch-all for designated information provides flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that Amazon''s Non-Public Information (''NPI'') includes: customer data and viewing information; content strategy and programming decisions; marketing plans and advertising rates; vendor and talent compensation information; and any information that a reasonable person would understand to be confidential given the circumstances of disclosure.', ARRAY['acknowledges','Non-Public Information','NPI','customer data','viewing information','content strategy','programming decisions','marketing plans','advertising rates','vendor','talent compensation','reasonable person','understand','confidential','circumstances']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "NPI definition with reasonableness standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific enumeration of NPI categories plus reasonableness standard ensures comprehensive coverage without requiring formal designation for obviously confidential information."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall use Confidential Information solely for the purpose of performing its obligations under this Agreement and shall not use such information for any other purpose, including for ProdCo''s own benefit or the benefit of any third party. ProdCo shall not reverse engineer, decompile, or derive source code from any Amazon technology.', ARRAY['use','Confidential Information','solely','purpose','performing obligations','Agreement','not use','other purpose','ProdCo''s own benefit','benefit','third party','not reverse engineer','decompile','derive source code','Amazon technology']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Use restriction with technology protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Purpose limitation restricts use to Agreement performance. Prohibition on reverse engineering protects Amazon technology that may be accessed during production."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall protect Confidential Information using at least the same degree of care it uses to protect its own confidential information of like kind, but in no event less than reasonable care. ProdCo shall implement appropriate technical and organizational measures to prevent unauthorized access, disclosure, or loss.', ARRAY['protect','Confidential Information','same degree of care','own confidential information','like kind','no event','less than reasonable care','implement','appropriate','technical','organizational measures','prevent','unauthorized access','disclosure','loss']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Care standard with security measures", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Dual care standard (same as own, no less than reasonable) sets appropriate protection level. Technical and organizational measure requirement addresses modern security expectations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose Confidential Information only to its employees, contractors, and agents who: (a) have a need to know such information for purposes of this Agreement; (b) have been informed of the confidential nature of the information; and (c) are bound by confidentiality obligations at least as protective as those set forth herein.', ARRAY['disclose','Confidential Information','only','employees','contractors','agents','need to know','purposes','Agreement','informed','confidential nature','bound','confidentiality obligations','at least as protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Limited disclosure with flow-down", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Need-to-know limitation with flow-down confidentiality requirements ensures protection extends to authorized recipients. Standard three-part requirement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall immediately notify Amazon upon becoming aware of any actual or suspected unauthorized access, disclosure, or use of Confidential Information. ProdCo shall cooperate with Amazon''s investigation and remediation efforts and shall take all reasonable steps to mitigate any harm from such breach.', ARRAY['immediately notify','Amazon','actual','suspected','unauthorized access','disclosure','use','Confidential Information','cooperate','investigation','remediation','take','reasonable steps','mitigate','harm','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Breach notification and cooperation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Immediate notification requirement for actual or suspected breaches with cooperation and mitigation obligations is essential for incident response."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations shall survive expiration or termination of this Agreement for a period of five (5) years, except that obligations regarding trade secrets shall survive for so long as such information remains a trade secret under applicable law.', ARRAY['confidentiality obligations','survive','expiration','termination','Agreement','five years','except','trade secrets','survive','so long as','remains','trade secret','applicable law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Survival period with trade secret exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-year post-termination survival is standard. Trade secret exception ensures indefinite protection for qualifying information."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain confidentiality of Amazon information. Confidential Information shall not include information that: (a) is or becomes publicly available without breach by ProdCo; (b) was rightfully in ProdCo''s possession prior to disclosure; (c) is independently developed by ProdCo without use of Confidential Information; or (d) is rightfully obtained from a third party without restriction.', ARRAY['maintain confidentiality','Confidential Information','not include','publicly available','without breach','rightfully','possession','prior to disclosure','independently developed','without use','rightfully obtained','third party','without restriction']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Standard exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard confidentiality exclusions are appropriate. Each exclusion has appropriate qualifiers (without breach, rightfully, without use, without restriction)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose Confidential Information if required by law, regulation, or legal process, provided that ProdCo: (a) gives Amazon prompt written notice to permit Amazon to seek a protective order; (b) discloses only the minimum information legally required; and (c) cooperates with Amazon''s efforts to protect the information.', ARRAY['disclose','Confidential Information','required by law','regulation','legal process','gives Amazon','prompt written notice','protective order','discloses','minimum','legally required','cooperates','efforts','protect']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Compelled disclosure exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Compelled disclosure exception with notice, minimization, and cooperation requirements is standard and appropriate. Allows legal compliance while protecting Amazon''s interests."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality obligations apply to Amazon information. ProdCo may share general, non-identifying information about its engagement with Amazon for purposes of business development, provided such disclosure does not reveal Agreement terms, Amazon strategies, or any NPI.', ARRAY['confidentiality obligations','Amazon information','share','general','non-identifying information','engagement','Amazon','business development','disclosure','not reveal','Agreement terms','Amazon strategies','NPI']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Limited business development disclosure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited general disclosure for business development (e.g., ''we work with major streamers'') may be acceptable if truly non-identifying and excluding all NPI and terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect Confidential Information. If ProdCo uses subcontractors who require access to Confidential Information, ProdCo shall: (a) obtain Amazon''s prior written approval of such subcontractor; (b) ensure subcontractor is bound by equivalent confidentiality terms; and (c) remain fully liable for subcontractor''s compliance.', ARRAY['protect','Confidential Information','subcontractors','require access','obtain','Amazon''s prior written approval','ensure','bound','equivalent confidentiality terms','remain','fully liable','subcontractor''s compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Subcontractor approval and liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Subcontractor approval requirement with equivalent terms and continued liability ensures confidentiality extends through supply chain. Prior approval allows Amazon vetting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon expiration or termination of this Agreement, or upon Amazon''s request, ProdCo shall promptly return or destroy all Confidential Information and certify such return or destruction in writing. ProdCo may retain one archival copy for legal compliance purposes only, subject to continuing confidentiality obligations.', ARRAY['expiration','termination','Agreement','Amazon''s request','promptly return','destroy','Confidential Information','certify','return','destruction','writing','retain','one archival copy','legal compliance','continuing confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Return/destroy with archival exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Return or destroy requirement with certification is standard. Single archival copy for legal compliance is reasonable exception given potential litigation discovery needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges that Confidential Information is valuable and that breach would cause irreparable harm for which monetary damages would be inadequate. ProdCo agrees that Amazon shall be entitled to seek injunctive relief without posting bond, in addition to any other remedies.', ARRAY['acknowledges','Confidential Information','valuable','breach','irreparable harm','monetary damages','inadequate','agrees','Amazon','entitled','seek injunctive relief','without posting bond','other remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Injunctive relief acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Irreparable harm acknowledgment and bond waiver for injunctive relief supports Amazon''s ability to obtain emergency protection against breaches."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain confidentiality of information expressly designated in writing as ''Confidential'' by Amazon at the time of disclosure. Information not so designated shall not be subject to confidentiality obligations.', ARRAY['maintain confidentiality','information','expressly designated','writing','Confidential','Amazon','time of disclosure','not designated','not subject to','confidentiality obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Written designation required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring written ''Confidential'' designation at disclosure creates massive gap. Most NPI is shared verbally or without formal marking. Confidentiality must apply to information reasonably understood as confidential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations shall expire upon expiration or termination of this Agreement. Post-termination, ProdCo shall have no further confidentiality obligations with respect to any Amazon information.', ARRAY['confidentiality obligations','expire','expiration','termination','Agreement','post-termination','no further','confidentiality obligations','Amazon information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No post-termination survival", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "No post-termination survival eliminates protection for confidential information shared during the relationship. Multi-year survival is essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain confidentiality using commercially reasonable efforts. ProdCo shall not be liable for inadvertent disclosures resulting from security breaches beyond ProdCo''s reasonable control.', ARRAY['maintain confidentiality','commercially reasonable efforts','not liable','inadvertent disclosures','security breaches','beyond','reasonable control']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Reasonable efforts with breach exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Commercially reasonable efforts'' is too low a standard for confidentiality. Breach exclusion eliminates liability for potentially negligent security failures. Strict confidentiality obligation is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall protect Amazon''s Confidential Information. This obligation shall not restrict ProdCo from disclosing information to: (a) any potential investor or acquirer; (b) ProdCo''s attorneys and accountants; or (c) any party in connection with ProdCo''s business operations.', ARRAY['protect','Confidential Information','not restrict','disclosing','potential investor','acquirer','attorneys','accountants','party','connection','business operations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Broad disclosure exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for investors, acquirers, and business operations are far too broad. Could permit disclosure to Amazon competitors. Any M&A disclosure requires Amazon approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations are mutual. Amazon''s confidentiality obligations to ProdCo shall be identical in scope and duration to ProdCo''s obligations to Amazon. Neither party shall have greater protection than the other.', ARRAY['confidentiality obligations','mutual','Amazon''s confidentiality obligations','ProdCo','identical','scope','duration','ProdCo''s obligations','Amazon','neither party','greater protection']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutual equivalence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual equivalence ignores that Amazon typically shares more sensitive information (NPI, strategy, data). ProdCo''s obligations should be comprehensive; Amazon''s can be more limited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations apply. ProdCo''s aggregate liability for breach of confidentiality shall not exceed $50,000 regardless of the nature or extent of the breach or the value of the information disclosed.', ARRAY['confidentiality obligations','apply','aggregate liability','breach','confidentiality','not exceed','$50,000','regardless','nature','extent','breach','value','information disclosed']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Liability cap on confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$50K cap on confidentiality breach liability is grossly inadequate given potential harm from NPI disclosure. Confidentiality breaches must be excluded from any liability limitations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain strict confidentiality regarding all creative elements of the Program, including without limitation: scripts, treatments, and outlines; storylines, plot points, and character arcs; casting decisions and talent attachments; visual designs and production artwork; and any other creative information that could spoil the viewing experience if disclosed.', ARRAY['maintain strict confidentiality','creative elements','Program','scripts','treatments','outlines','storylines','plot points','character arcs','casting decisions','talent attachments','visual designs','production artwork','spoil','viewing experience','disclosed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Creative confidentiality scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive creative confidentiality covering all elements that could constitute spoilers. Spoiler prevention is critical for content value protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that premature disclosure of Program creative elements could cause irreparable harm to Amazon by diminishing audience interest, enabling competitive response, or reducing the Program''s commercial value. ProdCo shall treat all creative information as highly sensitive.', ARRAY['acknowledges','premature disclosure','Program creative elements','irreparable harm','Amazon','diminishing','audience interest','competitive response','reducing','commercial value','treat','creative information','highly sensitive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Harm acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of harm from premature disclosure supports injunctive relief and establishes context for strict confidentiality requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Scripts and other written materials shall be distributed only on a need-to-know basis with unique watermarks identifying the recipient. ProdCo shall maintain a log of all script distributions and shall collect and destroy scripts following completion of relevant production activities.', ARRAY['scripts','written materials','distributed','need-to-know','unique watermarks','identifying','recipient','maintain','log','script distributions','collect','destroy','scripts','completion','relevant production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Script security protocols", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Watermarking, distribution logging, and collection/destruction protocols are industry-standard script security measures that enable tracking and limit exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall ensure that all cast, crew, and production personnel execute Amazon''s standard confidentiality and non-disclosure agreements prior to receiving any creative materials or commencing services. ProdCo shall maintain copies of such executed agreements and provide them to Amazon upon request.', ARRAY['ensure','cast','crew','production personnel','execute','Amazon''s standard','confidentiality','non-disclosure agreements','prior to','receiving','creative materials','commencing services','maintain copies','executed agreements','provide','Amazon','request']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Personnel NDA requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel NDA requirement with Amazon''s form ensures consistent protection. Execution before access and record-keeping enables enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement and enforce policies prohibiting: (a) photography, video recording, or audio recording on set without authorization; (b) posting of any production-related content on social media; (c) discussion of plot points or creative elements with unauthorized persons; and (d) removal of any creative materials from secure locations.', ARRAY['implement','enforce','policies','prohibiting','photography','video recording','audio recording','set','authorization','posting','production-related content','social media','discussion','plot points','creative elements','unauthorized persons','removal','creative materials','secure locations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "On-set security policies", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific prohibitions address common leak vectors including set photography, social media, and materials removal. Policy enforcement requirement creates accountability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any creative information is leaked or disclosed without authorization, ProdCo shall immediately notify Amazon, cooperate with Amazon''s investigation, and assist with containment and mitigation efforts. Amazon may direct ProdCo''s response to any leak situation.', ARRAY['creative information','leaked','disclosed','without authorization','immediately notify','Amazon','cooperate','investigation','assist','containment','mitigation','Amazon','direct','ProdCo''s response','leak situation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Leak response protocol", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Leak response protocol with immediate notification and Amazon direction ensures coordinated response. Amazon control over response is important for managing public relations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include confidentiality provisions equivalent to those set forth herein in all agreements with writers, directors, cast, and key crew. Failure of any such personnel to comply with confidentiality requirements shall not relieve ProdCo of its obligations to Amazon.', ARRAY['include','confidentiality provisions','equivalent','agreements','writers','directors','cast','key crew','failure','personnel','comply','confidentiality','not relieve','ProdCo','obligations','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Flow-down with continued liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement extends protection to personnel agreements. Continued ProdCo liability regardless of personnel breach ensures Amazon has recourse against responsible party."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Creative confidentiality applies. ProdCo may share general, non-spoiler information about its involvement in the production for purposes of industry recognition (e.g., award submissions, professional credits), subject to Amazon''s prior approval of the specific disclosure.', ARRAY['creative confidentiality','applies','share','general','non-spoiler information','involvement','production','industry recognition','award submissions','professional credits','Amazon''s prior approval','specific disclosure']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Industry recognition exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Industry recognition exception with Amazon approval may be acceptable for legitimate professional purposes. Prior approval requirement ensures Amazon control over what''s disclosed."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect creative elements. If ProdCo becomes aware of any third-party attempt to obtain or publish spoiler information, ProdCo shall notify Amazon immediately and shall not cooperate with or comment to any such third party without Amazon''s direction.', ARRAY['protect','creative elements','aware','third-party attempt','obtain','publish','spoiler information','notify Amazon','immediately','not cooperate','not comment','third party','Amazon''s direction']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Third-party inquiry handling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party inquiry protocol ensures Amazon awareness and control over responses. Non-cooperation without direction prevents inadvertent confirmations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Script security protocols apply. For audition purposes, ProdCo may provide audition sides (partial scenes) to casting candidates, provided such sides do not reveal major plot points, are watermarked with candidate identification, and are collected or destroyed following auditions.', ARRAY['script security','applies','audition purposes','provide','audition sides','partial scenes','casting candidates','not reveal','major plot points','watermarked','candidate identification','collected','destroyed','following auditions']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Audition sides exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Audition sides exception is operationally necessary for casting. Restrictions on content, watermarking, and collection/destruction maintain appropriate protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Creative confidentiality extends to location information. ProdCo shall not disclose specific filming locations in advance without Amazon approval, as such disclosure could enable paparazzi access, fan interference, or security threats to talent.', ARRAY['creative confidentiality','extends','location information','not disclose','specific filming locations','advance','Amazon approval','paparazzi access','fan interference','security threats','talent']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Location confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Location confidentiality addresses practical security and operational concerns. Advance disclosure restrictions prevent production disruptions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain creative confidentiality. Notwithstanding the foregoing, ProdCo may share creative elements with legitimate collaborators (composers, VFX vendors, post-production facilities) under written confidentiality agreements, provided ProdCo notifies Amazon of such disclosures quarterly.', ARRAY['maintain','creative confidentiality','notwithstanding','share','creative elements','legitimate collaborators','composers','VFX vendors','post-production facilities','written confidentiality agreements','notifies Amazon','disclosures','quarterly']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Collaborator sharing with reporting", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Production collaborator exception is operationally necessary. Quarterly reporting provides Amazon visibility without requiring per-disclosure approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Script watermarking applies. For large-scale productions, ProdCo may use electronic watermarking systems that embed recipient identification in digital files rather than visible watermarks, provided such systems are auditable and can trace any leaked materials to the source.', ARRAY['script watermarking','applies','large-scale productions','electronic watermarking systems','embed','recipient identification','digital files','visible watermarks','auditable','trace','leaked materials','source']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Electronic watermarking alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Electronic watermarking alternative for large productions is acceptable if traceable. Audit requirement ensures leak source identification capability is preserved."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to maintain confidentiality of creative elements. However, ProdCo shall not be responsible for disclosures by individual cast or crew members acting outside the scope of their employment.', ARRAY['reasonable efforts','maintain confidentiality','creative elements','not responsible','disclosures','individual cast','crew members','acting outside','scope','employment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Personnel exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' is inadequate standard, and personnel exclusion eliminates liability for most likely leak sources. ProdCo must be responsible for personnel it engages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Creative confidentiality applies until public announcement of the Program. Following Amazon''s public announcement of the Program''s existence, cast, and general premise, all creative confidentiality obligations shall terminate.', ARRAY['creative confidentiality','applies','until','public announcement','Program','following','Amazon''s public announcement','existence','cast','general premise','confidentiality obligations','terminate']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Termination upon announcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination of creative confidentiality upon announcement eliminates spoiler protection. Announcement reveals existence, not plot details. Creative elements must remain confidential through release."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain creative confidentiality. If a leak occurs despite ProdCo''s reasonable precautions, ProdCo shall not be liable for damages arising from such leak, as leaks are inherent risks in film production.', ARRAY['maintain creative confidentiality','leak occurs','despite','reasonable precautions','not liable','damages','arising from','leak','inherent risks','film production']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Leak liability exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Leak liability exclusion based on ''inherent risk'' eliminates accountability. ProdCo must be liable for leaks; ''reasonable precautions'' defense shifts burden to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Script distribution shall be at ProdCo''s discretion based on production needs. ProdCo shall not be required to implement watermarking, distribution logging, or other security measures that would impede efficient production operations.', ARRAY['script distribution','ProdCo''s discretion','production needs','not required','implement','watermarking','distribution logging','security measures','impede','efficient production operations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No security measures required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Discretionary distribution without security measures eliminates leak prevention and tracing capabilities. Watermarking and logging are essential and not unduly burdensome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Creative elements are confidential. Notwithstanding, ProdCo and its personnel may discuss their creative contributions to the Program with press and media to promote their own careers, provided they avoid revealing specific plot details that Amazon designates as embargoed.', ARRAY['creative elements','confidential','notwithstanding','ProdCo','personnel','discuss','creative contributions','Program','press','media','promote','careers','avoid revealing','specific plot details','Amazon designates','embargoed']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Press discussion exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Press discussion exception for ''career promotion'' creates uncontrolled disclosure channel. Any press communication must be coordinated with and approved by Amazon."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue, and shall ensure that its personnel do not issue, any press release, public announcement, or other publicity regarding this Agreement, the Program, or ProdCo''s relationship with Amazon without Amazon''s prior written approval, which approval may be withheld in Amazon''s sole discretion.', ARRAY['not issue','ensure','personnel','not issue','press release','public announcement','publicity','Agreement','Program','relationship','Amazon','prior written approval','withheld','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Standard publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive publicity restriction requiring prior written approval for any public communications. Sole discretion withholding preserves Amazon''s complete control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and exclusive control over all marketing, advertising, promotion, and publicity for the Program. ProdCo shall cooperate with Amazon''s publicity efforts as reasonably requested, including making talent available for promotional appearances, subject to talent availability.', ARRAY['Amazon','sole','exclusive control','marketing','advertising','promotion','publicity','Program','cooperate','publicity efforts','reasonably requested','talent available','promotional appearances','subject to','talent availability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Amazon publicity control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s exclusive publicity control with ProdCo cooperation requirement ensures coordinated promotional strategy. Talent availability qualifier is reasonable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Publicity restrictions apply to all forms of communication, including: press releases; media interviews; social media posts; website content; trade publication statements; speaking engagements; and any other public or semi-public communication regarding the Program or Agreement.', ARRAY['publicity restrictions','all forms','communication','press releases','media interviews','social media','website content','trade publication','speaking engagements','public','semi-public','communication','Program','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive communication scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumeration of covered communication types ensures comprehensive coverage including social media and speaking engagements. Semi-public qualifier addresses industry events."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include provisions in all talent and key personnel agreements requiring compliance with Amazon''s publicity guidelines and requiring prior Amazon approval for any public statements regarding the Program. Violation by personnel shall be a breach by ProdCo.', ARRAY['include provisions','talent','key personnel agreements','compliance','Amazon''s publicity guidelines','prior Amazon approval','public statements','Program','violation','personnel','breach','ProdCo']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Personnel flow-down with breach attribution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel agreement flow-down requirement with ProdCo breach attribution ensures accountability. Extends approval requirement to talent who may have direct media relationships."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, in its sole discretion, approve, modify, or reject any proposed publicity. If Amazon does not respond to a publicity request within ten (10) business days, such request shall be deemed rejected. Approval of specific publicity shall not constitute approval of any other publicity.', ARRAY['Amazon','sole discretion','approve','modify','reject','proposed publicity','not respond','publicity request','ten business days','deemed rejected','approval','specific publicity','not constitute','approval','other publicity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Approval mechanics with deemed rejection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Deemed rejection for non-response (rather than deemed approval) prevents inadvertent approvals. Each approval is specific, preventing scope expansion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use Amazon''s name, logo, trademarks, or other branding elements in any publicity or communication without Amazon''s prior written approval. Any approved use shall comply with Amazon''s brand guidelines as provided from time to time.', ARRAY['not use','Amazon''s name','logo','trademarks','branding elements','publicity','communication','prior written approval','approved use','comply','Amazon''s brand guidelines','provided','from time to time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Trademark use restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Trademark use restriction with brand guideline compliance ensures proper use of Amazon marks. Protects Amazon''s brand integrity in all public communications."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Following completion of the Program and public release, ProdCo may reference its involvement in the Program in general terms in company biographies, resumes, and professional portfolios, provided such references are factually accurate and do not imply Amazon endorsement of ProdCo.', ARRAY['following completion','Program','public release','reference','involvement','Program','general terms','company biographies','resumes','professional portfolios','factually accurate','not imply','Amazon endorsement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Post-release portfolio exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited post-release portfolio exception allows reasonable professional references. Accuracy and non-endorsement requirements provide appropriate guardrails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity requires Amazon approval. Amazon shall respond to publicity requests within five (5) business days of receipt of complete proposed materials. If Amazon fails to respond within such period, ProdCo may re-submit the request with notice that non-response within three (3) additional business days shall constitute approval.', ARRAY['publicity','Amazon approval','respond','publicity requests','five business days','receipt','complete proposed materials','fails to respond','re-submit','request','notice','non-response','three additional business days','constitute approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Response timeline with deemed approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval after re-submission and additional waiting period may be acceptable to address non-responsive situations. Total eight days plus re-submission provides adequate process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon approval is required for publicity. ProdCo may respond to unsolicited press inquiries with ''no comment'' or by referring the inquiry to Amazon''s publicity department without prior approval, provided ProdCo does not provide any substantive information.', ARRAY['Amazon approval','required','publicity','respond','unsolicited press inquiries','no comment','referring','inquiry','Amazon''s publicity department','without prior approval','not provide','substantive information']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "No comment exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''No comment'' or referral response to unsolicited inquiries is reasonable operational exception. No substantive information qualifier is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity approval is required. Amazon agrees to make reasonable efforts to respond to publicity requests promptly. For time-sensitive publicity opportunities, Amazon shall designate a point of contact available to provide expedited review and approval.', ARRAY['publicity approval','required','Amazon','reasonable efforts','respond','publicity requests','promptly','time-sensitive','publicity opportunities','designate','point of contact','expedited review','approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Expedited process commitment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon commitment to prompt response and expedited process for time-sensitive matters is reasonable operational accommodation without compromising approval right."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon approval for publicity. For publicity regarding industry awards (Emmy, Oscar, etc.) where timing is critical, Amazon shall pre-approve standard acceptance speech language and thank-you statements, subject to ProdCo''s submission for approval in advance of the award season.', ARRAY['Amazon approval','publicity','industry awards','Emmy','Oscar','timing','critical','pre-approve','standard acceptance speech language','thank-you statements','submission','approval','advance','award season']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Award speech pre-approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Award speech pre-approval process addresses practical reality of live events. Advance submission requirement gives Amazon opportunity to review and approve."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon approval required for publicity. ProdCo may share production stills and behind-the-scenes content with cast and crew for their personal archives, provided such materials are not publicly shared without Amazon approval and bear confidentiality notices.', ARRAY['Amazon approval','required','publicity','share','production stills','behind-the-scenes content','cast','crew','personal archives','not publicly shared','without Amazon approval','confidentiality notices']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal archive exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Personal archive sharing with non-public restriction is reasonable accommodation for personnel memories. Confidentiality notice requirement provides additional protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity restrictions apply. Amazon shall coordinate with ProdCo regarding the timing and content of major publicity announcements, and shall consider in good faith ProdCo''s input on publicity matters, though Amazon shall have final decision-making authority.', ARRAY['publicity restrictions','apply','Amazon','coordinate','ProdCo','timing','content','major publicity announcements','consider','good faith','ProdCo''s input','publicity matters','Amazon','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Coordination and input rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Coordination and good faith consideration of ProdCo input is reasonable collaboration without compromising Amazon''s final authority over publicity decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may issue press releases and publicity regarding its involvement in the Program, subject only to a requirement to notify Amazon of planned publicity at least 48 hours in advance. Amazon may object, but ProdCo shall have final discretion.', ARRAY['issue','press releases','publicity','involvement','Program','subject','notify Amazon','planned publicity','48 hours','advance','Amazon','object','ProdCo','final discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Notice only with ProdCo discretion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Notice-only requirement with ProdCo final discretion eliminates Amazon''s approval right. Amazon must have approval authority, not just objection opportunity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon approval is required for formal press releases. Informal publicity such as social media posts, interviews, and industry communications shall be at ProdCo''s discretion, provided ProdCo does not disparage Amazon.', ARRAY['Amazon approval','required','formal press releases','informal publicity','social media','interviews','industry communications','ProdCo''s discretion','not disparage','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Informal publicity exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excepting social media, interviews, and industry communications from approval creates massive uncontrolled publicity channel. All forms require approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity requires Amazon approval, which shall not be unreasonably withheld, conditioned, or delayed. Amazon''s failure to approve reasonable publicity requests shall entitle ProdCo to proceed with such publicity.', ARRAY['publicity','Amazon approval','not unreasonably withheld','conditioned','delayed','failure to approve','reasonable','publicity requests','entitle','ProdCo','proceed','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Unreasonable withholding standard", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Not unreasonably withheld'' standard with proceed-if-not-approved removes Amazon''s discretion. Amazon must have sole discretion over publicity approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity restrictions are mutual. Amazon shall not issue publicity regarding the Program or ProdCo without ProdCo''s prior written approval, on the same terms as ProdCo requires Amazon approval.', ARRAY['publicity restrictions','mutual','Amazon','not issue publicity','Program','ProdCo','ProdCo''s prior written approval','same terms','ProdCo requires','Amazon approval']::text[], '{"doc": "Counterparty_Proposal", "section": "Publicity", "note": "Mutual approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual approval requirement prevents Amazon from controlling its own publicity for its own content. Amazon owns and controls the Program; ProdCo cannot have approval over Amazon''s publicity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not issue publicity about the Program without approval. However, ProdCo''s principals and key creative personnel retain personal publicity rights and may discuss their involvement in the Program with press without Amazon approval.', ARRAY['not issue publicity','Program','without approval','however','ProdCo''s principals','key creative personnel','personal publicity rights','discuss','involvement','Program','press','without Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal publicity carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Personal publicity carveout for principals and key creatives creates uncontrolled disclosure channel through exactly the people with most information. All publicity requires approval regardless of who initiates."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement and enforce Amazon''s social media guidelines for all cast, crew, and production personnel. Such guidelines shall prohibit posting any content related to the production, including photos, videos, locations, scripts, or any other production-related information, without Amazon''s prior written approval.', ARRAY['implement','enforce','Amazon''s social media guidelines','cast','crew','production personnel','prohibit','posting','content','production','photos','videos','locations','scripts','production-related information','Amazon''s prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Standard social media restrictions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive social media restrictions with Amazon guidelines enforcement. Prohibits all production-related content without approval, addressing primary leak vector."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Cast members shall be permitted to post approved social media content only in accordance with a social media calendar coordinated with Amazon''s marketing team. All posts shall use designated hashtags, tagging, and content only. Spontaneous or uncoordinated posts regarding the Program are prohibited.', ARRAY['cast members','permitted','post','approved social media content','social media calendar','coordinated','Amazon''s marketing team','designated hashtags','tagging','content','spontaneous','uncoordinated posts','Program','prohibited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Coordinated cast social media", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Coordinated social media calendar with Amazon marketing ensures strategic timing and messaging. Prohibition on spontaneous posts prevents uncontrolled communications."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include in all cast and crew agreements a provision requiring: (a) compliance with Amazon''s social media policy; (b) immediate removal of any unauthorized posts upon Amazon''s request; (c) provision of social media account credentials to ProdCo for monitoring purposes if requested; and (d) consent to injunctive relief for violations.', ARRAY['include','cast','crew agreements','provision','compliance','Amazon''s social media policy','immediate removal','unauthorized posts','Amazon''s request','social media account credentials','monitoring','consent','injunctive relief','violations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Personnel agreement requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel flow-down of social media requirements with removal obligation, monitoring capability, and injunctive consent creates comprehensive enforcement framework."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Social media restrictions shall apply to all platforms, including without limitation: Instagram, Twitter/X, Facebook, TikTok, LinkedIn, YouTube, Snapchat, personal blogs, podcasts, and any other public or semi-public online communication platform, whether currently existing or developed in the future.', ARRAY['social media restrictions','apply','all platforms','Instagram','Twitter','X','Facebook','TikTok','LinkedIn','YouTube','Snapchat','personal blogs','podcasts','online communication platform','currently existing','developed','future']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Platform scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive platform enumeration with future-platform language ensures coverage regardless of social media evolution. Includes often-overlooked platforms like LinkedIn and podcasts."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any production personnel violates social media restrictions, ProdCo shall: (a) immediately require removal of the offending content; (b) notify Amazon within two (2) hours of becoming aware; (c) cooperate with Amazon''s response efforts; and (d) at Amazon''s request, remove the violating individual from the production.', ARRAY['production personnel','violates','social media restrictions','immediately require removal','offending content','notify Amazon','two hours','becoming aware','cooperate','Amazon''s response efforts','Amazon''s request','remove','violating individual','production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Violation response protocol", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Violation response protocol with short notification window and removal capability enables rapid containment. Personnel removal option provides meaningful consequence."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall designate a social media compliance officer responsible for: monitoring personnel social media accounts for production-related content; enforcing social media policies; coordinating approved posts with Amazon; and serving as the point of contact for social media issues.', ARRAY['designate','social media compliance officer','monitoring','personnel social media accounts','production-related content','enforcing','social media policies','coordinating','approved posts','Amazon','point of contact','social media issues']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Compliance officer requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Designated compliance officer creates accountability and operational structure for social media management. Single point of contact improves coordination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Production areas (sets, stages, production offices) shall be designated as phone-free or camera-restricted zones where photography and recording are prohibited. ProdCo shall post visible notices, provide secure storage for personal devices, and enforce these restrictions through on-set security personnel.', ARRAY['production areas','sets','stages','production offices','phone-free','camera-restricted zones','photography','recording','prohibited','visible notices','secure storage','personal devices','enforce','on-set security personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "On-set device restrictions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Device restrictions in production areas prevent content capture at source. Storage, notices, and security enforcement address practical implementation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions apply. Following public announcement of a cast member''s involvement (by Amazon), such cast member may acknowledge their participation in general terms on personal social media, without revealing creative details, plot information, or behind-the-scenes content.', ARRAY['social media restrictions','apply','following','public announcement','cast member''s involvement','Amazon','acknowledge','participation','general terms','personal social media','without revealing','creative details','plot information','behind-the-scenes content']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Post-announcement acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited acknowledgment after Amazon announcement may be acceptable given information is already public. General terms and content restrictions provide guardrails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions shall be enforced. For major cast (leads and series regulars), Amazon and ProdCo shall develop an individualized social media plan addressing the talent''s existing platform presence and follower expectations, while maintaining appropriate confidentiality protections.', ARRAY['social media restrictions','enforced','major cast','leads','series regulars','Amazon','ProdCo','develop','individualized social media plan','talent''s','existing platform presence','follower expectations','maintaining','confidentiality protections']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Individualized talent plans", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Individualized plans for major cast acknowledge their established social media presence and fan engagement. Confidentiality protection requirement ensures plans maintain appropriate restrictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Crew members may share non-revealing content (e.g., photos of catering, generic equipment shots without identifiable branding, wrap party celebrations after public release) with Amazon''s pre-approval. ProdCo shall submit proposed crew social media content for approval at least 48 hours in advance.', ARRAY['crew members','share','non-revealing content','photos','catering','generic equipment shots','without','identifiable branding','wrap party','public release','Amazon''s pre-approval','submit','proposed','crew social media content','approval','48 hours','advance']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Crew non-revealing content exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-revealing crew content exception with pre-approval may be acceptable for morale purposes. 48-hour submission window provides review time."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media compliance includes monitoring. ProdCo shall use commercially available social media monitoring tools to detect unauthorized production-related posts and shall provide Amazon with weekly reports during production and monthly reports during post-production.', ARRAY['social media compliance','monitoring','commercially available','social media monitoring tools','detect','unauthorized','production-related posts','provide','Amazon','weekly reports','production','monthly reports','post-production']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Monitoring with reporting", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Monitoring tool requirement and regular reporting provides visibility into social media landscape and early detection of potential issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'During the promotional period surrounding Program release, Amazon may request that cast participate in coordinated social media campaigns. ProdCo shall use reasonable efforts to ensure cast availability and cooperation, subject to any limitations in cast agreements and scheduling constraints.', ARRAY['promotional period','Program release','Amazon','request','cast','participate','coordinated social media campaigns','reasonable efforts','ensure','cast availability','cooperation','subject to','limitations','cast agreements','scheduling constraints']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Promotional campaign participation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Promotional campaign participation request with reasonable efforts and cast agreement constraints acknowledges practical realities while supporting Amazon''s marketing needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions apply. ProdCo acknowledges that influencer talent may have contractual obligations to brand partners requiring social media activity. Such activities shall be permitted provided they do not reference the Program and are disclosed to Amazon in advance.', ARRAY['social media restrictions','apply','acknowledges','influencer talent','contractual obligations','brand partners','social media activity','permitted','not reference','Program','disclosed','Amazon','advance']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Influencer brand obligation exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Influencer brand obligation acknowledgment with Program non-reference requirement and disclosure addresses modern talent realities while protecting production confidentiality."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to enforce social media restrictions. However, ProdCo cannot control the personal social media accounts of cast and crew and shall not be liable for their unauthorized posts.', ARRAY['reasonable efforts','enforce','social media restrictions','cannot control','personal social media accounts','cast','crew','not liable','unauthorized posts']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Reasonable efforts with no liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with no liability for personnel posts eliminates accountability. ProdCo must be responsible for personnel it engages regardless of control limitations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Social media restrictions shall not apply to cast members'' personal accounts. Cast retain full rights to use their personal social media platforms as they see fit, including posting about their professional activities.', ARRAY['social media restrictions','not apply','cast members''','personal accounts','retain','full rights','use','personal social media platforms','posting','professional activities']::text[], '{"doc": "Counterparty_Proposal", "section": "Social Media", "note": "Cast personal account exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excepting cast personal accounts eliminates primary restriction need. Cast are most visible and have largest followings; their posts are highest-risk leak vector."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may provide social media guidelines but cannot mandate compliance. Guild and union rules protect talent''s personal expression rights, and any attempt to restrict social media would violate such rules.', ARRAY['Amazon','provide','social media guidelines','cannot mandate','compliance','guild','union rules','protect','talent''s','personal expression rights','restrict','social media','violate','rules']::text[], '{"doc": "Counterparty_Proposal", "section": "Social Media", "note": "Guild/union override claim", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Guild/union rules do not prevent contractual social media restrictions regarding production content. This is false characterization; confidentiality requirements are standard and enforceable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Production personnel may post personal photos from set showing themselves with colleagues, provided such photos do not reveal ''major spoilers'' as defined by Amazon. Non-spoiler behind-the-scenes content is permitted.', ARRAY['production personnel','post','personal photos','set','showing themselves','colleagues','not reveal','major spoilers','defined','Amazon','non-spoiler','behind-the-scenes content','permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Non-spoiler BTS permitted", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Behind-the-scenes permission even with ''non-spoiler'' qualifier creates uncontrolled content flow. BTS photos can reveal sets, costumes, and other protectable elements. All production photos require approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Social media restrictions apply during production only. Once principal photography wraps, cast and crew may post freely about their experience working on the Program, subject only to not revealing major plot points that have not been publicly released.', ARRAY['social media restrictions','apply','during production only','principal photography wraps','cast','crew','post freely','experience','working on','Program','not revealing','major plot points','not','publicly released']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Production-only restrictions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Production-only restrictions eliminate protection during post-production and pre-release marketing window. Restrictions must continue through release and coordinated promotional period."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Confidentiality obligations shall survive expiration or termination of this Agreement for a period of five (5) years, except that: (a) obligations regarding trade secrets shall survive indefinitely; (b) obligations regarding personal data shall survive for so long as such data is retained; and (c) obligations regarding NPI shall survive for seven (7) years.', ARRAY['confidentiality obligations','survive','expiration','termination','Agreement','five years','except','trade secrets','survive indefinitely','personal data','survive','so long as','data','retained','NPI','survive','seven years']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Tiered survival periods", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tiered survival periods based on information type appropriately differentiates protection needs. Trade secret indefinite survival and extended NPI period reflect heightened sensitivity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon expiration or termination of this Agreement, or upon Amazon''s request at any time, ProdCo shall: (a) immediately cease using all Confidential Information; (b) within ten (10) business days, return to Amazon or securely destroy all Confidential Information in any form; and (c) provide written certification of compliance.', ARRAY['expiration','termination','Agreement','Amazon''s request','any time','immediately cease using','Confidential Information','ten business days','return','Amazon','securely destroy','Confidential Information','any form','written certification','compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Return or destroy with certification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard return/destroy obligation with timeline and certification. On-request provision allows Amazon to require action at any time, not just termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Destruction of Confidential Information shall be completed using secure methods appropriate to the medium: physical documents shall be shredded; electronic files shall be securely deleted using industry-standard data destruction software; and cloud-stored information shall be permanently deleted with confirmation from the cloud provider.', ARRAY['destruction','Confidential Information','secure methods','appropriate','medium','physical documents','shredded','electronic files','securely deleted','industry-standard','data destruction software','cloud-stored','permanently deleted','confirmation','cloud provider']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Destruction standards by medium", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Media-specific destruction standards ensure appropriate methods for each format. Cloud provider confirmation addresses modern storage realities."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The return or destruction obligation extends to Confidential Information held by ProdCo''s agents, contractors, and subcontractors. ProdCo shall ensure such parties return or destroy Confidential Information on the same timeline and shall obtain and provide certifications from such parties.', ARRAY['return','destruction obligation','extends','Confidential Information','agents','contractors','subcontractors','ensure','parties','return','destroy','same timeline','obtain','provide','certifications','parties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Third-party return/destroy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extension to third parties with certification requirement ensures complete information recovery. Prevents residual information in supply chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following provisions shall survive expiration or termination of this Agreement: confidentiality obligations; publicity restrictions; indemnification obligations; representations and warranties; limitation of liability; dispute resolution; and any other provision that by its nature should survive.', ARRAY['provisions','survive','expiration','termination','Agreement','confidentiality','publicity restrictions','indemnification','representations','warranties','limitation of liability','dispute resolution','provision','nature','should survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Comprehensive survival provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumeration of surviving provisions ensures key protections continue post-termination. Catch-all for nature-based survival addresses unenumerated provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations regarding Program creative elements shall survive until such elements have been publicly released by Amazon. Following public release, confidentiality obligations regarding those specific elements shall terminate, but obligations regarding unreleased elements and Amazon NPI shall continue.', ARRAY['confidentiality obligations','Program creative elements','survive','publicly released','Amazon','public release','confidentiality obligations','specific elements','terminate','unreleased elements','Amazon NPI','continue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Release-based creative survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Release-based survival for creative elements is practical approach. Distinguishes between released content (public) and unreleased content (still confidential)."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, at any time upon reasonable notice, conduct an audit to verify ProdCo''s compliance with confidentiality obligations, including verification of return or destruction of Confidential Information. ProdCo shall cooperate with such audits and provide access to relevant systems and personnel.', ARRAY['Amazon','any time','reasonable notice','conduct','audit','verify','ProdCo''s compliance','confidentiality obligations','verification','return','destruction','Confidential Information','cooperate','audits','access','systems','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Audit right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Audit right for confidentiality compliance verification provides enforcement mechanism. System and personnel access enables meaningful verification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality survives termination. ProdCo may retain one archival copy of Confidential Information solely for purposes of legal compliance and dispute resolution, provided such copy is stored securely, accessed only by authorized legal personnel, and destroyed upon resolution of any pending legal matters.', ARRAY['confidentiality survives','termination','retain','one archival copy','Confidential Information','legal compliance','dispute resolution','stored securely','accessed','authorized legal personnel','destroyed','resolution','pending legal matters']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Legal archival exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Single archival copy for legal purposes with security, access, and destruction requirements is reasonable exception addressing litigation and regulatory needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Return or destruction applies to Confidential Information. Information that has been incorporated into routine backup systems and cannot reasonably be identified and deleted may be retained subject to continuing confidentiality obligations, provided ProdCo uses reasonable efforts to delete such information when backups are rotated.', ARRAY['return','destruction','applies','Confidential Information','incorporated','routine backup systems','cannot reasonably','identified','deleted','retained','continuing confidentiality obligations','reasonable efforts','delete','backups','rotated']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Backup retention exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Backup exception acknowledges technical reality that commingled backup data is difficult to selectively delete. Continuing obligations and rotation-based deletion provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival of confidentiality is five years from termination. For information that remains a trade secret after five years, ProdCo''s obligations shall continue, but the determination of trade secret status shall be based on then-current law and circumstances.', ARRAY['survival','confidentiality','five years','termination','information','remains','trade secret','five years','obligations','continue','determination','trade secret status','then-current law','circumstances']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Trade secret determination clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Trade secret continuation with then-current law determination is reasonable legal framework. Protects information that retains trade secret status while not overreaching."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall return or destroy Confidential Information within thirty (30) days of termination. If destruction is not feasible due to technical limitations, ProdCo shall notify Amazon and propose an alternative approach, which Amazon may accept or reject.', ARRAY['return','destroy','Confidential Information','thirty days','termination','destruction','not feasible','technical limitations','notify Amazon','propose','alternative approach','Amazon','accept','reject']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Extended timeline with alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Thirty-day timeline is slightly longer but may be acceptable. Technical limitation alternative with Amazon approval addresses practical challenges while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, ProdCo shall certify return or destruction. If Amazon disputes the completeness of compliance, Amazon may request specific verification measures, and ProdCo shall cooperate, provided such measures are reasonable and do not require disclosure of ProdCo''s privileged information.', ARRAY['termination','certify','return','destruction','Amazon disputes','completeness','compliance','request','specific verification measures','cooperate','reasonable','not require','disclosure','ProdCo''s privileged information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Dispute verification with privilege protection", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Verification cooperation with privilege protection addresses legitimate concern while enabling compliance verification. Reasonableness requirement prevents overreaching."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival period is five years. ProdCo acknowledges that during such period, it remains bound by confidentiality obligations and may be required to respond to Amazon inquiries, litigation discovery, or regulatory investigations regarding Confidential Information.', ARRAY['survival period','five years','acknowledges','during period','bound','confidentiality obligations','required','respond','Amazon inquiries','litigation discovery','regulatory investigations','Confidential Information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Post-termination cooperation acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of ongoing obligations and cooperation requirements during survival period sets clear expectations for post-termination conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations shall terminate upon expiration or termination of this Agreement. Following termination, ProdCo shall have no further confidentiality obligations with respect to any information disclosed during the term.', ARRAY['confidentiality obligations','terminate','expiration','termination','Agreement','following termination','no further','confidentiality obligations','information','disclosed','term']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "No survival", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "No survival of confidentiality obligations eliminates all post-termination protection. Confidential information shared during the term requires ongoing protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality survives for one (1) year following termination. This period reflects the practical reality that most information loses its competitive value within one year and that longer periods impose unreasonable burdens on ProdCo.', ARRAY['confidentiality survives','one year','following termination','practical reality','information','loses','competitive value','one year','longer periods','unreasonable burdens','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "One-year survival only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year survival is grossly inadequate. Content-related confidential information retains value for years. Minimum five-year survival is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall return or destroy Confidential Information upon request. However, ProdCo shall not be required to return or destroy information that has been incorporated into ProdCo''s work product, internal systems, or institutional knowledge.', ARRAY['return','destroy','Confidential Information','upon request','not required','return','destroy','information','incorporated','ProdCo''s work product','internal systems','institutional knowledge']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Work product/systems exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for work product, systems, and ''institutional knowledge'' creates massive loophole. Allows ProdCo to retain virtually all information. Return/destroy must be comprehensive."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Return or destruction applies to physical documents only. Electronic information may be retained in ProdCo''s systems subject to ProdCo''s standard data retention policies, which ProdCo may modify at any time.', ARRAY['return','destruction','applies','physical documents only','electronic information','retained','ProdCo''s systems','standard data retention policies','modify','any time']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Physical only return", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting return/destroy to physical documents while allowing electronic retention defeats the purpose. Most confidential information is electronic and must be covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall certify return or destruction within ninety (90) days of termination. Certification by ProdCo shall be conclusive evidence of compliance, and Amazon shall have no right to audit or verify such certification.', ARRAY['certify','return','destruction','ninety days','termination','certification','ProdCo','conclusive evidence','compliance','Amazon','no right','audit','verify','certification']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Conclusive certification without audit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ninety-day timeline is too long, and conclusive certification without audit right eliminates verification ability. Amazon must retain audit rights to verify compliance."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Survival and return obligations are mutual. Amazon shall return or destroy ProdCo''s Confidential Information on the same terms, and Amazon''s confidentiality obligations shall survive for the same period as ProdCo''s.', ARRAY['survival','return obligations','mutual','Amazon','return','destroy','ProdCo''s Confidential Information','same terms','Amazon''s confidentiality obligations','survive','same period','ProdCo''s']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutual return/destroy", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual obligations ignore that Amazon receives far more confidential information from ProdCo than vice versa. Amazon''s obligations can be more limited given asymmetric information flow."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by and construed in accordance with the laws of the State of California, without regard to its conflict of laws principles. The parties irrevocably submit to the exclusive jurisdiction and venue of the state and federal courts located in Los Angeles County, California.', ARRAY['governed by','construed','laws','State of California','without regard to','conflict of laws','irrevocably submit','exclusive jurisdiction','venue','state','federal courts','Los Angeles County','California']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Standard California choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "California law with Los Angeles venue is standard for entertainment industry agreements. Conflict of laws exclusion prevents forum shopping arguments. Exclusive jurisdiction creates certainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by the laws of the State of Washington. Any action arising out of or relating to this Agreement shall be brought exclusively in the state or federal courts located in King County, Washington. The parties consent to personal jurisdiction in such courts and waive any objection to venue.', ARRAY['governed by','laws','State of Washington','action','arising out of','relating to','brought exclusively','state','federal courts','King County','Washington','consent','personal jurisdiction','waive','objection','venue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Washington choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Washington law with King County venue is appropriate given Amazon''s headquarters location. Personal jurisdiction consent and venue waiver strengthen enforceability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The laws of the State of New York shall govern this Agreement without regard to principles of conflicts of law. The parties agree that the state and federal courts sitting in New York County, New York shall have exclusive jurisdiction over any disputes and waive any defense of inconvenient forum.', ARRAY['laws','State of New York','govern','without regard to','conflicts of law','state','federal courts','New York County','exclusive jurisdiction','disputes','waive','defense','inconvenient forum']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "New York choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "New York law and venue is standard alternative to California for entertainment agreements. Forum non conveniens waiver prevents dismissal motions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by California law. The United Nations Convention on Contracts for the International Sale of Goods and any uniform laws based thereon shall not apply to this Agreement.', ARRAY['governed by','California law','United Nations Convention','Contracts','International Sale of Goods','uniform laws','not apply','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "CISG exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "CISG exclusion is standard for U.S. agreements with international counterparties. Prevents application of international treaty that might otherwise govern."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party irrevocably waives any right to trial by jury in any action or proceeding arising out of or relating to this Agreement. The parties acknowledge that this waiver is knowing and voluntary and has been negotiated as part of the bargained-for exchange.', ARRAY['irrevocably waives','right','trial by jury','action','proceeding','arising out of','relating to','Agreement','waiver','knowing','voluntary','negotiated','bargained-for exchange']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Jury waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Jury waiver is standard in commercial agreements and preferred for complex entertainment disputes. Acknowledgment of knowing/voluntary waiver supports enforceability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The choice of law and venue provisions herein are material terms of this Agreement. ProdCo agrees that it has had the opportunity to consult with counsel regarding these provisions and has knowingly and voluntarily agreed to California law and Los Angeles venue.', ARRAY['choice of law','venue provisions','material terms','Agreement','opportunity','consult','counsel','knowingly','voluntarily','agreed','California law','Los Angeles venue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Counsel acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Counsel acknowledgment reinforces enforceability of choice of law and venue provisions. Establishes that provisions were knowingly accepted."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the exclusive venue provision, Amazon may bring an action for injunctive relief, specific performance, or enforcement of any judgment in any court of competent jurisdiction worldwide. ProdCo consents to jurisdiction in any such court for such purposes.', ARRAY['notwithstanding','exclusive venue','Amazon','bring action','injunctive relief','specific performance','enforcement','judgment','court','competent jurisdiction','worldwide','consents','jurisdiction','purposes']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Worldwide enforcement carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveout for worldwide enforcement of injunctive relief and judgments allows Amazon to pursue relief where assets or activities are located."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement shall be governed by California law. For disputes arising primarily from production activities conducted in a non-U.S. jurisdiction, the parties agree to consult regarding appropriate venue, provided that California law shall remain applicable regardless of venue.', ARRAY['governed by','California law','disputes','arising primarily','production activities','non-U.S. jurisdiction','consult','appropriate venue','California law','remain applicable','regardless','venue']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Non-U.S. production venue consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Venue consultation for non-U.S. production disputes may be acceptable while maintaining California law. Provides flexibility for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law governs. Either party may serve process on the other by any means permitted by California law, including service by overnight courier to the notice address specified herein. Service shall be deemed complete upon delivery.', ARRAY['California law','governs','serve process','any means','permitted','California law','service','overnight courier','notice address','specified','service','deemed complete','delivery']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Alternative service provision", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Alternative service provision facilitating overnight courier service is practical addition that doesn''t limit forum selection. Streamlines process initiation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Agreement is governed by California law. For intellectual property disputes involving rights registered outside the United States, such disputes may be brought in courts of the country where the rights are registered, applying California law to the extent permitted.', ARRAY['governed by','California law','intellectual property disputes','rights registered','outside','United States','brought','courts','country','rights registered','applying','California law','extent permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Foreign IP registration forum", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Foreign IP registration forum option acknowledges that some IP disputes may need to be brought where rights are registered. California law application preserves consistency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law and Los Angeles venue apply. If either party is required to enforce a judgment in a foreign jurisdiction, such party shall use reasonable efforts to seek recognition under applicable treaties or conventions. The other party shall not oppose such recognition proceedings.', ARRAY['California law','Los Angeles venue','apply','enforce','judgment','foreign jurisdiction','reasonable efforts','seek recognition','applicable treaties','conventions','not oppose','recognition proceedings']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Foreign judgment recognition cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Foreign judgment recognition cooperation provision facilitates international enforcement. Non-opposition covenant prevents obstruction of legitimate enforcement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement is governed by California law. ProdCo agrees that any action brought by ProdCo against Amazon must be brought in California courts within two (2) years of the claim accruing, and ProdCo waives any longer limitations period that might otherwise apply.', ARRAY['governed by','California law','action','brought','ProdCo','against Amazon','California courts','two years','claim accruing','waives','longer limitations period','otherwise apply']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Shortened limitations period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Two-year contractual limitations period is enforceable in California and provides reasonable window while limiting stale claims. One-sided application benefits Amazon."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law governs. The parties acknowledge that California has a substantial relationship to this Agreement and that application of California law is reasonable. ProdCo waives any argument that California law should not apply or that another jurisdiction''s law is more appropriate.', ARRAY['California law','governs','acknowledge','California','substantial relationship','Agreement','application','California law','reasonable','waives','argument','California law','not apply','another jurisdiction''s law','more appropriate']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Relationship acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Substantial relationship acknowledgment and waiver of challenge supports enforceability. Prevents later arguments that choice of law was unreasonable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by the laws of the jurisdiction in which ProdCo is incorporated. Venue shall be in the courts of such jurisdiction. Amazon consents to jurisdiction in such courts.', ARRAY['governed by','laws','jurisdiction','ProdCo','incorporated','venue','courts','such jurisdiction','Amazon consents','jurisdiction']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo home jurisdiction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s home jurisdiction for law and venue is unacceptable. Amazon requires consistent forum (California, Washington, or New York) for all production agreements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties agree that any dispute shall be resolved in the jurisdiction where the majority of production activities occurred. Choice of law shall be the law of such jurisdiction.', ARRAY['dispute','resolved','jurisdiction','majority','production activities occurred','choice of law','law','such jurisdiction']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Production location forum", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Production location forum creates unpredictable jurisdiction that varies by project. Amazon requires consistent forum regardless of production location."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party may bring actions in its home jurisdiction. Amazon agrees to submit to the jurisdiction of courts in ProdCo''s jurisdiction for any action brought by ProdCo against Amazon.', ARRAY['each party','bring actions','home jurisdiction','Amazon','submit','jurisdiction','courts','ProdCo''s jurisdiction','action','brought','ProdCo','against Amazon']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Split home jurisdictions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Split home jurisdiction forum allows ProdCo to sue Amazon in ProdCo''s home court. Amazon requires exclusive venue in Amazon''s chosen forum."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'No exclusive venue applies. Either party may bring an action in any court of competent jurisdiction where the other party does business, has assets, or can otherwise be served.', ARRAY['no exclusive venue','applies','either party','bring action','court','competent jurisdiction','other party','does business','has assets','served']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No exclusive venue", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Non-exclusive venue allows forum shopping and creates unpredictability. Exclusive venue in Amazon''s chosen forum is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by international commercial law principles, including UNIDROIT Principles and lex mercatoria. National law shall apply only where international principles are silent.', ARRAY['governed by','international commercial law principles','UNIDROIT Principles','lex mercatoria','national law','apply','only','international principles','silent']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "International law principles", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "International law principles instead of U.S. state law creates uncertainty. Entertainment agreements require specific U.S. state law governing."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'California law governs. However, if any provision of this Agreement is unenforceable under California law but would be enforceable under the law of ProdCo''s jurisdiction, such other law shall apply to that provision.', ARRAY['California law','governs','provision','Agreement','unenforceable','California law','enforceable','law','ProdCo''s jurisdiction','other law','apply','provision']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Alternative law for unenforceability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Alternative law application for unenforceable provisions creates unpredictable hybrid governing law. California law must apply uniformly; if provisions are unenforceable, severability applies."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any dispute, controversy, or claim arising out of or relating to this Agreement, including its formation, interpretation, performance, breach, or termination, shall be resolved exclusively by binding arbitration administered by JAMS in accordance with its Comprehensive Arbitration Rules.', ARRAY['dispute','controversy','claim','arising out of','relating to','Agreement','formation','interpretation','performance','breach','termination','resolved exclusively','binding arbitration','administered','JAMS','Comprehensive Arbitration Rules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "JAMS arbitration clause", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "JAMS arbitration with comprehensive coverage is standard for entertainment agreements. Binding arbitration provides finality and confidentiality."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. The arbitration shall be conducted by a single arbitrator with entertainment industry experience, mutually agreed by the parties. If the parties cannot agree on an arbitrator within fifteen (15) days, JAMS shall appoint one.', ARRAY['disputes','resolved','arbitration','conducted','single arbitrator','entertainment industry experience','mutually agreed','parties','cannot agree','arbitrator','fifteen days','JAMS','appoint']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Single arbitrator with industry experience", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Single arbitrator for efficiency with entertainment industry experience requirement ensures qualified decision-maker. Fallback to JAMS appointment prevents deadlock."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Arbitration is the exclusive remedy for disputes except that either party may seek: (a) injunctive or other equitable relief in any court of competent jurisdiction; (b) provisional remedies under applicable law; or (c) enforcement of any arbitration award in any court of competent jurisdiction.', ARRAY['arbitration','exclusive remedy','disputes','except','either party','seek','injunctive','equitable relief','court','competent jurisdiction','provisional remedies','applicable law','enforcement','arbitration award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitration with court carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveouts for injunctive relief, provisional remedies, and award enforcement preserve ability to seek emergency relief while maintaining arbitration for substantive disputes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to award any remedy that would be available in court, including compensatory damages, specific performance, and injunctive relief. The arbitrator shall not have authority to award punitive or exemplary damages, and the parties waive any right thereto.', ARRAY['arbitrator','authority','award','remedy','available in court','compensatory damages','specific performance','injunctive relief','not have authority','award','punitive','exemplary damages','parties waive','right']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitrator authority with punitive damages waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad arbitrator remedial authority with punitive damages exclusion is standard commercial approach. Ensures adequate relief while limiting unpredictable awards."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitration award shall be final and binding. Judgment on the award may be entered in any court of competent jurisdiction. The parties waive any right to appeal the award except as provided by the Federal Arbitration Act for vacatur of arbitration awards.', ARRAY['arbitration award','final','binding','judgment','award','entered','court','competent jurisdiction','waive','right to appeal','except','Federal Arbitration Act','vacatur','arbitration awards']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Final and binding with limited appeal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Finality with FAA vacatur exception is standard. Waiver of broader appeal rights preserves arbitration efficiency while maintaining statutory protections."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Arbitration proceedings shall be confidential. Neither party shall disclose the existence, content, or results of the arbitration, except as required by law or to enforce the arbitration award. The arbitrator shall have authority to issue protective orders regarding confidential information.', ARRAY['arbitration proceedings','confidential','neither party','disclose','existence','content','results','arbitration','except','required by law','enforce','arbitration award','arbitrator','authority','protective orders','confidential information']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitration confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Arbitration confidentiality is key advantage over litigation. Protective order authority enables handling of sensitive business information."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the agreement to arbitrate, Amazon may elect to litigate any dispute in court by providing written notice to ProdCo prior to commencement of arbitration. ProdCo shall not have the corresponding right to elect litigation.', ARRAY['notwithstanding','agreement to arbitrate','Amazon','elect','litigate','dispute','court','written notice','ProdCo','prior to','commencement','arbitration','ProdCo','not have','corresponding right','elect litigation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Amazon litigation election option", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon-only litigation election option provides flexibility for disputes that may be better suited to court while maintaining arbitration as default."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. For disputes involving claimed damages of less than $250,000, the parties agree to streamlined arbitration procedures with limited discovery and expedited timelines as set forth in Exhibit [X].', ARRAY['disputes','resolved','arbitration','disputes','claimed damages','less than $250,000','streamlined arbitration procedures','limited discovery','expedited timelines','Exhibit']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Small claims streamlined procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Streamlined procedures for smaller disputes reduces cost and time. $250K threshold and specific exhibit terms provide clarity on when streamlined process applies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration applies to all disputes. Either party may request a panel of three arbitrators for disputes involving claimed damages exceeding $5,000,000, with costs of the additional arbitrators shared equally regardless of outcome.', ARRAY['arbitration','applies','all disputes','either party','request','panel','three arbitrators','disputes','claimed damages exceeding','$5,000,000','costs','additional arbitrators','shared equally','regardless','outcome']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Three-arbitrator panel option for large disputes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-arbitrator panel option for large disputes provides additional review for significant matters. Equal cost sharing is fair approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be arbitrated. The parties agree to use JAMS unless JAMS is unavailable, in which case AAA shall administer the arbitration. Selection of an alternative administrator requires mutual written agreement.', ARRAY['disputes','arbitrated','use JAMS','unless','JAMS','unavailable','AAA','administer','arbitration','selection','alternative administrator','mutual written agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "JAMS with AAA backup", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "AAA as backup administrator if JAMS unavailable ensures arbitration can proceed. Both are reputable institutions with entertainment experience."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration is the exclusive remedy. The arbitrator shall issue a reasoned written decision explaining the factual and legal basis for the award. The decision shall be issued within sixty (60) days of the close of the evidentiary hearing.', ARRAY['arbitration','exclusive remedy','arbitrator','issue','reasoned written decision','explaining','factual','legal basis','award','decision','issued','sixty days','close','evidentiary hearing']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Reasoned decision requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasoned decision requirement improves transparency and provides basis for any vacatur challenge. 60-day timeline ensures timely resolution."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Binding arbitration applies. The Federal Arbitration Act shall govern the interpretation and enforcement of this arbitration agreement. State arbitration law shall apply only to the extent not preempted by the FAA.', ARRAY['binding arbitration','applies','Federal Arbitration Act','govern','interpretation','enforcement','arbitration agreement','state arbitration law','apply','only','extent','not preempted','FAA']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "FAA governance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "FAA governance provides strong federal policy favoring arbitration. Clarifies that state law is preempted to extent inconsistent with FAA."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be arbitrated except that disputes solely regarding payment amounts may, at the option of either party, be submitted to a single accounting arbitrator for expedited determination based on documentary evidence only.', ARRAY['disputes','arbitrated','except','disputes','solely','payment amounts','option','either party','submitted','single accounting arbitrator','expedited determination','documentary evidence only']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Payment dispute expedited process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Expedited accounting arbitration for payment disputes is efficient for disputes involving calculations rather than legal issues. Either party option is balanced."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Disputes may be resolved by arbitration only if both parties mutually agree in writing at the time the dispute arises. Absent such agreement, disputes shall be resolved in court.', ARRAY['disputes','resolved','arbitration','only if','both parties','mutually agree','writing','time','dispute arises','absent','agreement','disputes','resolved','court']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Optional arbitration only", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Mutual agreement at time of dispute effectively eliminates arbitration since parties rarely agree once dispute exists. Arbitration must be mandatory and binding."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may elect to resolve any dispute through arbitration or litigation at ProdCo''s sole option. Amazon shall be bound by ProdCo''s election and shall not have the right to select a different forum.', ARRAY['ProdCo','elect','resolve','dispute','arbitration','litigation','ProdCo''s sole option','Amazon','bound','ProdCo''s election','not have','right','select','different forum']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo-only forum election", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-only forum election gives ProdCo complete control over dispute forum. Amazon must have forum election rights or exclusive arbitration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All disputes shall be resolved by litigation in court. The parties agree that arbitration is not an appropriate forum for entertainment industry disputes given the complexity and public interest in such matters.', ARRAY['all disputes','resolved','litigation','court','parties agree','arbitration','not','appropriate forum','entertainment industry disputes','complexity','public interest']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Mandatory litigation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory litigation eliminates arbitration benefits (confidentiality, speed, entertainment expertise). Arbitration is standard and appropriate for entertainment disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Arbitration shall not apply to claims that could be brought in small claims court. For claims under $75,000, either party may elect small claims court in the party''s home jurisdiction.', ARRAY['arbitration','not apply','claims','small claims court','claims','under $75,000','either party','elect','small claims court','party''s home jurisdiction']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Small claims exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Small claims exception for claims up to $75K in party''s home jurisdiction creates forum-shopping opportunity for significant claims. Arbitration must cover all disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The prevailing party in arbitration or litigation shall be entitled to recover reasonable attorneys'' fees from the non-prevailing party. ''Prevailing party'' shall be determined by the finder of fact.', ARRAY['prevailing party','arbitration','litigation','entitled','recover','reasonable attorneys'' fees','non-prevailing party','prevailing party','determined','finder of fact']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Loser pays fee shifting", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Prevailing party fee shifting creates significant risk if Amazon loses on any claim. Amazon typically prefers each party bearing own fees except for specific carveouts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. Any arbitration award shall be subject to de novo review by a court upon request of either party. The court''s determination shall supersede the arbitration award.', ARRAY['disputes','resolved','arbitration','arbitration award','subject to','de novo review','court','request','either party','court''s determination','supersede','arbitration award']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Court de novo review", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "De novo court review completely defeats arbitration benefits. Arbitration would become non-binding preliminary step. Awards must be final subject only to FAA vacatur."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in Los Angeles, California under the JAMS Comprehensive Arbitration Rules and Procedures in effect at the time of filing. The language of the arbitration shall be English. The arbitration shall be administered by JAMS.', ARRAY['arbitration','conducted','Los Angeles','California','JAMS Comprehensive Arbitration Rules','Procedures','in effect','time of filing','language','arbitration','English','administered','JAMS']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "JAMS comprehensive rules in LA", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Los Angeles is entertainment industry center with qualified arbitrators. JAMS Comprehensive Rules are appropriate for commercial disputes. English language ensures consistency."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Discovery in arbitration shall be limited to: (a) exchange of relevant documents; (b) up to five (5) depositions per side, each lasting no more than seven (7) hours; and (c) written interrogatories limited to twenty-five (25) questions per side. The arbitrator may permit additional discovery for good cause.', ARRAY['discovery','arbitration','limited','exchange','relevant documents','five depositions','per side','seven hours','written interrogatories','twenty-five questions','per side','arbitrator','permit','additional discovery','good cause']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Limited discovery parameters", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited discovery preserves arbitration efficiency while providing adequate fact-finding. Good cause exception allows expansion for complex matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The evidentiary hearing shall be conducted over no more than five (5) consecutive business days unless the arbitrator determines that additional time is necessary. Post-hearing briefs shall be submitted within thirty (30) days of the hearing''s conclusion.', ARRAY['evidentiary hearing','conducted','no more than','five','consecutive business days','unless','arbitrator determines','additional time','necessary','post-hearing briefs','submitted','thirty days','hearing''s conclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Hearing duration limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-day hearing limit promotes efficiency. Arbitrator discretion for additional time addresses complex matters. Thirty-day brief deadline provides adequate preparation time."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party shall bear its own costs and attorneys'' fees in the arbitration. The administrative fees of JAMS and the arbitrator''s fees and expenses shall be shared equally by the parties, subject to the arbitrator''s authority to reallocate such costs in the final award.', ARRAY['each party','bear','own costs','attorneys'' fees','arbitration','administrative fees','JAMS','arbitrator''s fees','expenses','shared equally','parties','subject to','arbitrator''s authority','reallocate','costs','final award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Cost allocation with reallocation authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Each party bearing own fees is standard commercial approach. Equal sharing of arbitration costs with reallocation authority is fair and provides incentive against frivolous claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall be a retired judge or attorney with at least fifteen (15) years of experience in entertainment law, including experience with production agreements, content licensing, or related matters. The arbitrator shall disclose any potential conflicts of interest.', ARRAY['arbitrator','retired judge','attorney','fifteen years','experience','entertainment law','production agreements','content licensing','related matters','disclose','potential conflicts of interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitrator qualifications", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific entertainment law experience requirement ensures qualified arbitrator. Fifteen years is appropriate for complex disputes. Conflict disclosure is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall apply California substantive law and shall not have authority to apply equity or principles of law that would result in a different outcome than would be reached by strict application of California law. The arbitrator shall not add to or modify the Agreement.', ARRAY['arbitrator','apply','California substantive law','not have authority','apply equity','principles of law','different outcome','strict application','California law','not add to','modify','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Substantive law constraints", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Constraints on equity application and Agreement modification limit arbitrator discretion to legal interpretation. Ensures predictability and faithful contract enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All arbitration proceedings, including filings, evidence, testimony, and awards, shall be treated as confidential information. Neither party shall disclose any aspect of the arbitration except as necessary to enforce the award or as required by law.', ARRAY['arbitration proceedings','filings','evidence','testimony','awards','treated','confidential information','neither party','disclose','aspect','arbitration','except','necessary','enforce','award','required by law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Comprehensive arbitration confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive confidentiality covering all aspects of arbitration is key benefit. Exceptions for enforcement and legal requirements are necessary and appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration shall be in Los Angeles or, at Amazon''s election, by videoconference. If conducted by videoconference, the parties shall use a secure platform approved by JAMS. Witnesses may testify remotely with parties'' consent or arbitrator permission.', ARRAY['arbitration','Los Angeles','Amazon''s election','videoconference','conducted','videoconference','secure platform','approved','JAMS','witnesses','testify remotely','parties'' consent','arbitrator permission']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Videoconference option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Videoconference option provides flexibility and cost savings. Amazon election right ensures choice remains with Amazon. Secure platform and witness appearance rules address practical concerns."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'JAMS Comprehensive Rules apply. Notwithstanding such rules, the arbitrator shall not have authority to order depositions of non-party witnesses except upon showing of compelling need and unavailability of information through other means.', ARRAY['JAMS Comprehensive Rules','apply','notwithstanding','arbitrator','not have authority','order depositions','non-party witnesses','except','showing','compelling need','unavailability','information','other means']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Non-party deposition limits", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-party deposition limits reduce burden on third parties while preserving access with compelling need showing. Consistent with limited discovery approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The arbitration shall proceed on an expedited basis if either party so requests and the claimed damages do not exceed $500,000. Expedited arbitration shall be completed within ninety (90) days of arbitrator appointment.', ARRAY['arbitration','proceed','expedited basis','either party','requests','claimed damages','not exceed','$500,000','expedited arbitration','completed','ninety days','arbitrator appointment']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Expedited arbitration for smaller claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Expedited option for smaller claims promotes efficiency. Either party request trigger and $500K threshold are reasonable parameters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The arbitrator may conduct a preliminary hearing to address discovery scope, hearing schedule, and procedural issues. The parties shall cooperate to complete arbitration within twelve (12) months of filing, absent extraordinary circumstances.', ARRAY['arbitrator','conduct','preliminary hearing','address','discovery scope','hearing schedule','procedural issues','parties','cooperate','complete','arbitration','twelve months','filing','absent','extraordinary circumstances']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Preliminary hearing and timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preliminary hearing for procedural matters is efficient practice. Twelve-month target provides reasonable timeline with flexibility for complex matters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If the arbitrator becomes unavailable after appointment, the parties shall select a replacement using the same process. The replacement arbitrator shall determine whether prior proceedings must be repeated or can be adopted.', ARRAY['arbitrator','becomes unavailable','after appointment','parties','select','replacement','same process','replacement arbitrator','determine','prior proceedings','repeated','adopted']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Arbitrator replacement procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Replacement procedure addresses practical contingency of arbitrator unavailability. Flexibility on prior proceedings adoption is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The evidentiary rules shall be relaxed in arbitration. The arbitrator may consider any evidence relevant to the dispute regardless of admissibility under formal rules of evidence, giving appropriate weight based on reliability and relevance.', ARRAY['evidentiary rules','relaxed','arbitration','arbitrator','consider','evidence','relevant','dispute','regardless','admissibility','formal rules','evidence','appropriate weight','reliability','relevance']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Relaxed evidentiary rules", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Relaxed evidentiary rules are common in arbitration and allow consideration of all relevant information. Weight-based approach provides appropriate flexibility."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in ProdCo''s home city using the rules of the local bar association arbitration program. Amazon shall bear all costs of arbitration regardless of outcome.', ARRAY['arbitration','conducted','ProdCo''s home city','rules','local bar association','arbitration program','Amazon','bear','all costs','arbitration','regardless','outcome']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo location with Amazon costs", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo home city venue and Amazon bearing all costs regardless of outcome is one-sided. Venue must be Amazon''s choice; costs should be shared or allocated by arbitrator."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Full federal court discovery rules shall apply in arbitration. Either party may take unlimited depositions and propound unlimited interrogatories. The arbitration schedule shall accommodate full discovery.', ARRAY['full federal court','discovery rules','apply','arbitration','either party','unlimited depositions','unlimited interrogatories','arbitration schedule','accommodate','full discovery']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Unlimited discovery", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unlimited federal court-style discovery defeats arbitration efficiency benefits. Discovery must be limited and proportionate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted using AAA Entertainment Industry Arbitration Rules. All arbitration hearings shall be held in New York City regardless of the governing law or any venue provisions.', ARRAY['arbitration','conducted','AAA Entertainment Industry Arbitration Rules','arbitration hearings','held','New York City','regardless','governing law','venue provisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Inconsistent venue with rules", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Overriding venue provisions with different arbitration location creates inconsistency. Arbitration location must align with governing law venue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to award reasonable attorneys'' fees and costs to the prevailing party. ''Prevailing party'' means the party that achieves substantially all of its claimed relief.', ARRAY['arbitrator','authority','award','reasonable attorneys'' fees','costs','prevailing party','prevailing party means','party','achieves','substantially all','claimed relief']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Prevailing party fee shifting", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Prevailing party fee shifting creates significant risk exposure if Amazon doesn''t achieve substantially all relief. Each party bearing own fees is preferred."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitrator may appoint independent experts at the parties'' expense to investigate any factual matters. Expert fees shall be borne by the party against whom the expert''s conclusions favor.', ARRAY['arbitrator','appoint','independent experts','parties'' expense','investigate','factual matters','expert fees','borne','party','against whom','expert''s conclusions','favor']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Appointed expert with outcome-based cost", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Outcome-based expert cost allocation creates unpredictable expense exposure. Expert costs should be shared or subject to arbitrator''s general cost allocation authority."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in the international language of the party initiating the claim. If ProdCo initiates and requests proceedings in a non-English language, Amazon shall provide certified translations at its expense.', ARRAY['arbitration','conducted','international language','party','initiating','claim','ProdCo initiates','requests','proceedings','non-English language','Amazon','provide','certified translations','expense']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Non-English proceedings option", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Non-English proceedings with Amazon translation expense burden is unacceptable. Arbitration must be conducted in English regardless of initiating party."}'::jsonb)
